import React from "react";
import Navbar from "../components/Navbar";

export default function Hire() {
  return (
    <div>
      <Navbar />
      <div style={{ padding: "30px" }}>
        <h1>Hire a Professional</h1>
        <p>Select a service and hire a trusted professional easily.</p>
      </div>
    </div>
  );
}
